// A small entry point beside the existing runtime files. No extraction or installation.
// LauncherBuild is generated by scripts/build-launcher.py at compile time.
using System;
using System.Diagnostics;
using System.IO;
using System.Reflection;
using System.Text;
using System.Windows.Forms;

internal static class GuiLauncher
{
    [STAThread]
    private static int Main(string[] args)
    {
        Application.EnableVisualStyles();
        try
        {
            string entry = Path.GetFullPath(Assembly.GetExecutingAssembly().Location);
            string launcherRoot = Path.GetDirectoryName(entry);
            string rootPrefix = launcherRoot.TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar) + Path.DirectorySeparatorChar;
            string relative = LauncherBuild.GuiRelativePath.Replace('/', Path.DirectorySeparatorChar);
            if (Path.IsPathRooted(relative) || relative.IndexOf(':') >= 0)
                throw new InvalidOperationException("GUI 入口必须位于启动器目录内。");
            string gui = Path.GetFullPath(Path.Combine(launcherRoot, relative));
            if (!gui.StartsWith(rootPrefix, StringComparison.OrdinalIgnoreCase) || String.Equals(gui, entry, StringComparison.OrdinalIgnoreCase))
                throw new InvalidOperationException("GUI 入口路径无效，不能跳出启动器目录或指向自身。");
            if (!File.Exists(gui))
                throw new FileNotFoundException("未找到桌面界面程序：\r\n" + gui + "\r\n\r\n请保留完整运行包，将 GUI 放在上述位置后重试。现有后端和配置不会被修改。");
            // A relative link must not redirect the GUI outside the distributed folder.
            if ((File.GetAttributes(gui) & FileAttributes.ReparsePoint) != 0)
                throw new IOException("GUI 程序不能是指向其他位置的链接。");
            for (DirectoryInfo directory = new DirectoryInfo(Path.GetDirectoryName(gui));
                 directory != null && !String.Equals(directory.FullName.TrimEnd(Path.DirectorySeparatorChar), launcherRoot.TrimEnd(Path.DirectorySeparatorChar), StringComparison.OrdinalIgnoreCase);
                 directory = directory.Parent)
                if ((directory.Attributes & FileAttributes.ReparsePoint) != 0)
                    throw new IOException("GUI 目录不能包含指向其他位置的链接。");

            string runtimeRelative = LauncherBuild.RuntimeRelativePath.Replace('/', Path.DirectorySeparatorChar);
            if (Path.IsPathRooted(runtimeRelative) || runtimeRelative.IndexOf(':') >= 0)
                throw new InvalidOperationException("运行目录必须位于启动器目录内。");
            string runtimeRoot = Path.GetFullPath(Path.Combine(launcherRoot, runtimeRelative));
            if (!String.Equals(runtimeRoot, launcherRoot, StringComparison.OrdinalIgnoreCase) &&
                !runtimeRoot.StartsWith(rootPrefix, StringComparison.OrdinalIgnoreCase))
                throw new InvalidOperationException("运行目录不能跳出启动器目录。");
            if (!Directory.Exists(runtimeRoot)) throw new DirectoryNotFoundException("未找到现有运行目录：\r\n" + runtimeRoot + "\r\n\r\n请保留完整运行包后重试。");
            for (DirectoryInfo directory = new DirectoryInfo(runtimeRoot);
                 directory != null && !String.Equals(directory.FullName.TrimEnd(Path.DirectorySeparatorChar), launcherRoot.TrimEnd(Path.DirectorySeparatorChar), StringComparison.OrdinalIgnoreCase);
                 directory = directory.Parent)
                if ((directory.Attributes & FileAttributes.ReparsePoint) != 0)
                    throw new IOException("运行目录不能包含指向其他位置的链接。");

            string stateArgument = null;
            foreach (string argument in args)
            {
                if (!argument.StartsWith("--state-dir=", StringComparison.Ordinal) || argument.Length <= 12)
                    throw new ArgumentException("不支持的启动参数：" + argument);
                if (stateArgument != null) throw new ArgumentException("只能指定一个 --state-dir 参数。");
                stateArgument = "--state-dir=" + Path.GetFullPath(argument.Substring(12));
            }
            if (stateArgument == null && LauncherBuild.DefaultStateRelativePath != null)
            {
                string stateRelative = LauncherBuild.DefaultStateRelativePath.Replace('/', Path.DirectorySeparatorChar);
                if (Path.IsPathRooted(stateRelative) || stateRelative.IndexOf(':') >= 0)
                    throw new InvalidOperationException("默认配置目录必须位于启动器目录内。");
                string stateRoot = Path.GetFullPath(Path.Combine(launcherRoot, stateRelative));
                if (!String.Equals(stateRoot, launcherRoot, StringComparison.OrdinalIgnoreCase) &&
                    !stateRoot.StartsWith(rootPrefix, StringComparison.OrdinalIgnoreCase))
                    throw new InvalidOperationException("默认配置目录不能跳出启动器目录。");
                for (DirectoryInfo directory = new DirectoryInfo(stateRoot);
                     directory != null && !String.Equals(directory.FullName.TrimEnd(Path.DirectorySeparatorChar), launcherRoot.TrimEnd(Path.DirectorySeparatorChar), StringComparison.OrdinalIgnoreCase);
                     directory = directory.Parent)
                    if (directory.Exists && (directory.Attributes & FileAttributes.ReparsePoint) != 0)
                        throw new IOException("默认配置目录不能包含指向其他位置的链接。");
                stateArgument = "--state-dir=" + stateRoot;
            }
            ProcessStartInfo start = new ProcessStartInfo
            {
                FileName = gui,
                Arguments = Quote("--runtime-root=" + runtimeRoot) + (stateArgument == null ? "" : " " + Quote(stateArgument)),
                WorkingDirectory = runtimeRoot,
                UseShellExecute = false
            };
            start.EnvironmentVariables["ZVIEWER_GUI_LAUNCHER"] = entry;
            // The GUI owns its existing single-instance, tray and process lifecycle behavior.
            using (Process process = Process.Start(start)) { }
            return 0;
        }
        catch (Exception ex)
        {
            MessageBox.Show("无法打开 ZViewer 界面。\r\n\r\n" + ex.Message, "ZViewer", MessageBoxButtons.OK, MessageBoxIcon.Error);
            return 1;
        }
    }

    private static string Quote(string value)
    {
        StringBuilder output = new StringBuilder("\"");
        int slashes = 0;
        foreach (char character in value)
        {
            if (character == '\\') { slashes++; continue; }
            if (character == '"') { output.Append('\\', slashes * 2 + 1).Append(character); slashes = 0; continue; }
            output.Append('\\', slashes).Append(character); slashes = 0;
        }
        return output.Append('\\', slashes * 2).Append('"').ToString();
    }
}
